import {MIN_PITCH,MAX_PITCH,DEFAULT_PITCH,REST_ZOOM} from './aiming.js';
export const ACTIONS=[['forward','Move forward'],['back','Move back'],['left','Move left'],['right','Move right'],['lookUp','Look up'],['lookDown','Look down'],['lookLeft','Look left'],['lookRight','Look right'],['fire','Throw / fire'],['jump','Jump'],['crouch','Crouch / duck'],['dodge','Dodge'],['catch','Catch'],['resetCamera','Reset camera']];
export const PAD_ACTIONS=[['fire','Throw / fire'],['catch','Catch'],['jump','Jump'],['crouch','Crouch / duck'],['dodge','Dodge'],['resetCamera','Reset camera']];
export const PAD_BUTTONS=[[0,'A / Cross'],[1,'B / Circle'],[2,'X / Square'],[3,'Y / Triangle'],[4,'LB / L1'],[5,'RB / R1'],[6,'LT / L2'],[7,'RT / R2'],[8,'View / Share'],[10,'Left stick press'],[11,'Right stick press'],[12,'D-pad up'],[13,'D-pad down'],[14,'D-pad left'],[15,'D-pad right']];
const STORAGE_KEY='potatoman.preferences.v1';
const keyDefaults=[{forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD',lookUp:'KeyT',lookDown:'KeyG',lookLeft:'KeyQ',lookRight:'KeyH',fire:'KeyF',jump:'Space',crouch:'ControlLeft',dodge:'ShiftLeft',catch:'KeyE',resetCamera:'KeyR'},{forward:'ArrowUp',back:'ArrowDown',left:'ArrowLeft',right:'ArrowRight',lookUp:'KeyI',lookDown:'KeyK',lookLeft:'KeyJ',lookRight:'KeyL',fire:'ControlRight',jump:'Numpad0',crouch:'Numpad1',dodge:'Enter',catch:'ShiftRight',resetCamera:'KeyN'}];
export function defaults(){return{version:8,roundSeconds:120,fov:70,zoom:REST_ZOOM,remix:true,sensitivity:1,panSensitivity:1,invertY:false,quality:'high',sound:true,music:true,musicVolume:.32,voice:true,voiceVolume:.85,voiceName:'',difficulty:'chill',keys:keyDefaults.map(o=>({...o})),mouse:{fire:0},pad:[{fire:7,catch:6,jump:0,crouch:11,dodge:1,resetCamera:3},{fire:7,catch:6,jump:0,crouch:11,dodge:1,resetCamera:3}]};}
export function validKey(code){return typeof code==='string'&&/^(Key[A-Z]|Digit[0-9]|Numpad(?:[0-9]|Add|Subtract|Multiply|Divide|Decimal|Enter)|Arrow(?:Up|Down|Left|Right)|Space|Enter|Shift(?:Left|Right)|Control(?:Left|Right)|Backspace|Delete|Insert|Home|End|PageUp|PageDown|Comma|Period|Slash|Semicolon|Quote|BracketLeft|BracketRight|Backslash|Minus|Equal|Backquote)$/.test(code);}
const num=(v,lo,hi,f)=>typeof v==='number'&&Number.isFinite(v)?Math.max(lo,Math.min(hi,v)):f;
export function validateSettings(input){const out=defaults();if(!input||typeof input!=='object')return out;
 out.roundSeconds=Math.round(num(input.roundSeconds,60,600,120)/30)*30;out.sensitivity=num(input.sensitivity,.3,2,1);out.panSensitivity=num(input.panSensitivity,.3,2,1);
 if(input.version>=6&&[-1,0,1,2].includes(input.mouse?.fire))out.mouse.fire=input.mouse.fire;
 out.fov=num(input.fov,50,100,70);out.zoom=num(input.zoom,3,9,REST_ZOOM);if((input.version??0)<7&&input.zoom===5.6)out.zoom=REST_ZOOM;
 for(const k of['invertY','sound','music','remix'])if(typeof input[k]==='boolean')out[k]=input[k];if(input.version>=3&&typeof input.voice==='boolean')out.voice=input.voice;out.musicVolume=num(input.musicVolume,0,1,.32);out.voiceVolume=num(input.voiceVolume,0,1,.85);if(input.version>=8&&typeof input.voiceName==='string')out.voiceName=input.voiceName.slice(0,250);if(['chill','easy','normal','hard'].includes(input.difficulty))out.difficulty=input.difficulty;if(['cinematic','high','performance'].includes(input.quality))out.quality=input.quality;
 if(Array.isArray(input.keys)&&input.keys.length===2){input={...input,keys:input.keys.map(o=>({...o}))};if((input.version??0)<6&&input.keys[0]?.jump==='KeyC'&&input.keys[0]?.dodge==='Space'){const occupied=input.keys.flatMap(o=>Object.values(o??{}));input.keys[0].jump='Space';input.keys[0].dodge=occupied.includes('ShiftLeft')?'KeyC':'ShiftLeft';}const used=new Set(input.keys.flatMap(o=>Object.values(o??{})));for(let i=0;i<2;i++)for(const action of['jump','crouch'])if(!input.keys[i]?.[action]){const k=[keyDefaults[i][action],...Array.from({length:26},(_,n)=>'Key'+String.fromCharCode(65+n)),...Array.from({length:10},(_,n)=>'Numpad'+n)].find(k=>!used.has(k));input.keys[i][action]=k;used.add(k);}const codes=input.keys.flatMap(o=>ACTIONS.map(([a])=>o?.[a]));if(codes.every(validKey)&&new Set(codes).size===codes.length)out.keys=input.keys.map(o=>Object.fromEntries(ACTIONS.map(([a])=>[a,o[a]])));}
 if(Array.isArray(input.pad))for(let i=0;i<2;i++){input.pad[i]={...input.pad[i]};for(const action of['jump','crouch'])if(input.pad[i][action]===undefined)input.pad[i][action]=[out.pad[i][action],...PAD_BUTTONS.map(([id])=>id)].find(id=>!Object.values(input.pad[i]).includes(id));const values=PAD_ACTIONS.map(([a])=>input.pad[i]?.[a]);if(values.every(v=>PAD_BUTTONS.some(([id])=>id===v))&&new Set(values).size===values.length)out.pad[i]=Object.fromEntries(PAD_ACTIONS.map(([a])=>[a,input.pad[i][a]]));}return out;
}
export function loadSettings(storage){try{return validateSettings(JSON.parse(storage?.getItem(STORAGE_KEY)??'null'));}catch{return defaults();}}
export function saveSettings(settings,storage){try{if(!storage)return false;storage.setItem(STORAGE_KEY,JSON.stringify(settings));return true;}catch{return false;}}
export function bindKey(settings,player,action,code){if(!validKey(code))return{ok:false,message:'Use a letter, number, arrow or modifier key. Escape is always Pause.'};const old=settings.keys[player][action];let swapped=null;for(let i=0;i<2;i++)for(const[a,label]of ACTIONS)if(settings.keys[i][a]===code&&(i!==player||a!==action)){settings.keys[i][a]=old;swapped=`Player ${i+1} · ${label}`;}settings.keys[player][action]=code;return{ok:true,message:swapped?`Swapped with ${swapped}.`:'Binding saved.'};}
export function bindButton(settings,group,player,action,value){if(group==='mouse'){if(action!=='fire'||![-1,0,1,2].includes(value))return false;settings.mouse.fire=value;return true;}if(group!=='pad'||!PAD_ACTIONS.some(([a])=>a===action)||!PAD_BUTTONS.some(([id])=>id===value))return false;const map=settings.pad[player],old=map[action];for(const other of Object.keys(map))if(other!==action&&map[other]===value){map[other]=old;break;}map[action]=value;return true;}
export function keyLabel(code){const labels={Space:'Space',Enter:'Enter',ArrowUp:'↑',ArrowDown:'↓',ArrowLeft:'←',ArrowRight:'→',ControlRight:'Right Ctrl',ControlLeft:'Left Ctrl',ShiftRight:'Right Shift',ShiftLeft:'Left Shift'};return labels[code]??code?.replace(/^Key/,'').replace(/^Digit/,'').replace(/^Numpad/,'Num ')??'—';}
export function mouseButtonHeld(button,buttons){return button>=0&&!!(buttons&[1,4,2][button]);}
export function cameraDrag(p,dx,dy,kind,settings){if(kind==='look'){p.yaw+=dx*.0055*settings.sensitivity;p.pitch=Math.max(MIN_PITCH,Math.min(MAX_PITCH,(p.pitch??0)+(settings.invertY?1:-1)*dy*.0022*settings.sensitivity));}else if(kind==='pan'){p.panX=Math.max(-2,Math.min(2,(p.panX??0)-dx*.012*settings.panSensitivity));p.panY=Math.max(-.8,Math.min(1.2,(p.panY??0)+dy*.009*settings.panSensitivity));}}
export function resetCamera(p){p.panX=0;p.panY=0;p.cameraDistance=REST_ZOOM;p.pitch=DEFAULT_PITCH;}
// Stick and thumb players cannot flick the view back level the way a mouse does, so once they
// stop aiming and start moving again the pitch walks itself home. Active aiming always wins.
export const AUTO_LEVEL_DELAY=.9;
export function autoLevel(p,dt,aiming,moving){p.aimIdle=aiming?0:(p.aimIdle??0)+Math.max(0,dt);
 if(aiming||!moving||p.aimIdle<AUTO_LEVEL_DELAY)return false;const ease=1-Math.exp(-2.6*Math.max(0,dt));
 p.pitch=(p.pitch??DEFAULT_PITCH)+(DEFAULT_PITCH-(p.pitch??DEFAULT_PITCH))*ease;p.panX=(p.panX??0)*(1-ease);p.panY=(p.panY??0)*(1-ease);return true;}
